import json
import sys
import collections

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def parseListNode(s):
    vals = json.loads(s)
    if not vals: return None
    head = ListNode(vals[0])
    curr = head
    for v in vals[1:]:
        curr.next = ListNode(v)
        curr = curr.next
    return head

def parseTreeNode(s):
    s = s.strip()
    if not s or s == "[]" or s == "[null]": return None
    if s.startswith("["): s = s[1:]
    if s.endswith("]"): s = s[:-1]
    tokens = [t.strip() for t in s.split(',')]
    if not tokens or tokens[0] == "null": return None
    root = TreeNode(int(tokens[0]))
    q = collections.deque([root])
    i = 1
    while q and i < len(tokens):
        curr = q.popleft()
        if i < len(tokens) and tokens[i] != "null":
            curr.left = TreeNode(int(tokens[i]))
            q.append(curr.left)
        i += 1
        if i < len(tokens) and tokens[i] != "null":
            curr.right = TreeNode(int(tokens[i]))
            q.append(curr.right)
        i += 1
    return root

def serializeListNode(head):
    res = []
    curr = head
    while curr:
        res.append(curr.val)
        curr = curr.next
    return json.dumps(res)

def serializeTreeNode(root):
    if not root: return "[]"
    res = []
    q = collections.deque([root])
    while q:
        curr = q.popleft()
        if curr:
            res.append(str(curr.val))
            q.append(curr.left)
            q.append(curr.right)
        else:
            res.append("null")
    while res and res[-1] == "null":
        res.pop()
    return "[" + ",".join(res) + "]"

